widget.solution:
def strategy_card(legs):
    """The card: cost, best, worst, breakevens."""
    def _profit(S):
        total = 0.0
        for kind, qty, strike, premium in legs:
            if kind == "call":
                total += qty * (max(S - strike, 0) - premium)
            elif kind == "put":
                total += qty * (max(strike - S, 0) - premium)
            else:
                total += qty * (S - strike)
        return total

    cost = 0.0
    for kind, qty, strike, premium in legs:
        cost += qty * (strike if kind == "stock" else premium)

    # Profit is a straight line between strikes, so check £0, each strike, and the slope beyond.
    points = sorted({0.0} | {float(k) for kind, q, k, p in legs if kind != "stock"})
    values = [_profit(S) for S in points]
    slope = sum(q for kind, q, k, p in legs if kind != "put")
    best = float("inf") if slope > 0 else max(values)
    worst = float("-inf") if slope < 0 else min(values)

    zero = 1e-9
    roots = []
    for a, b, pa, pb in zip(points, points[1:], values, values[1:]):
        if abs(pa) < zero:
            roots.append(a)
        elif abs(pb) >= zero and (pa < 0) != (pb < 0):
            roots.append(a + (b - a) * pa / (pa - pb))
    last = values[-1]
    if abs(last) < zero:
        roots.append(points[-1])
    elif slope != 0 and (last < 0) != (slope < 0):
        roots.append(points[-1] - last / slope)
    return {"cost": cost, "best": best, "worst": worst, "breakevens": roots}
